
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_sb98_1c_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_sb98_1c", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.554854237852793e+00, -3.487331608109260e+00, -3.392758679703363e+00, -3.261851365359786e+00, -3.083713868751781e+00, -2.847221970512168e+00, -2.544335228283432e+00, -2.176233793063509e+00, -1.761682375129663e+00, -1.337841321739123e+00, -9.165741008561437e-01, -6.160320557007253e-01, -5.326716020217980e-01, -4.387185505443967e-01, -3.178375675356369e-01, -2.003213101065575e-01, -1.172717986077904e-01, -5.119314503398600e-02, -1.212744546950721e-02, -1.415464998277468e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


